<?php
declare(strict_types=1);
require_once __DIR__.'/../../../src/auth.php'; require_once __DIR__.'/../../../src/audio.php';require_once __DIR__.'/../../../src/progress.php'; require_once __DIR__.'/../../../src/corrections.php'; header('Content-Type: application/json; charset=utf-8');
$u=require_student();$pdo=db(); if(empty($_FILES['audio']['tmp_name'])){http_response_code(422);echo json_encode(['error'=>'Áudio obrigatório.']);exit;} $target=trim((string)($_POST['target_text']??'')); if($target===''){http_response_code(422);echo json_encode(['error'=>'target_text é obrigatório.']);exit;}
try{$mime=(string)($_FILES['audio']['type']??'audio/webm');$dur=(float)($_POST['duration_seconds']??0);$tr=transcribe_audio_file($_FILES['audio']['tmp_name'],$mime);$cmp=compare_pronunciation_words($target,$tr['text']);$fb=build_pronunciation_feedback($cmp);$sp=synthesize_speech($target,'coral',0.9,'mp3');$sv=save_voice_bytes($sp['bytes'],'mp3');$s=$pdo->prepare("INSERT INTO pronunciation_attempts(student_id,target_text,transcription,similarity_score,matched_words,missing_words,unexpected_words,audio_mime,audio_duration_seconds,feedback,model_audio_path) VALUES(:student_id,:target_text,:transcription,:similarity_score,CAST(:matched_words AS jsonb),CAST(:missing_words AS jsonb),CAST(:unexpected_words AS jsonb),:audio_mime,:duration,:feedback,:model_audio_path) RETURNING id");$s->execute(['student_id'=>$u['student_id'],'target_text'=>$target,'transcription'=>$tr['text'],'similarity_score'=>$cmp['similarity_score'],'matched_words'=>json_encode($cmp['matched_words']),'missing_words'=>json_encode($cmp['missing_words']),'unexpected_words'=>json_encode($cmp['unexpected_words']),'audio_mime'=>$mime,'duration'=>$dur?:null,'feedback'=>$fb,'model_audio_path'=>$sv['relative']]);echo json_encode(['ok'=>true,'attempt_id'=>$s->fetchColumn(),'target_text'=>$target,'transcription'=>$tr['text'],'similarity_score'=>$cmp['similarity_score'],'matched_words'=>$cmp['matched_words'],'missing_words'=>$cmp['missing_words'],'unexpected_words'=>$cmp['unexpected_words'],'feedback'=>$fb,'model_audio_url'=>$sv['url'],'notice'=>'Comparação entre frase-alvo e transcrição; não é avaliação fonética clínica.'],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
